INSERT INTO evidence.source_policy_claim_fitness(source_policy_id,source_policy_version,claim_class,fitness,limitations,assessment_basis) VALUES ('collection-nps-nominations','1','record_fact','conditional',ARRAY['Compilations inherit the gaps of the moment they were made','Trace identity and chronology to the underlying documents; omissions do not establish absence','Nomination narratives can repeat errors and omissions. Government hosting does not make all passages primary records.','Designation records establish designation; broader significance and firstness require their own evidence.']::text[],'qualitative_review');
